package dev.admutium.techmod.test;
import dev.admutium.techmod.conveyor.*;
import dev.admutium.techmod.machine.*;
import dev.admutium.techmod.energy.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.ServerLevelData;
import net.minecraft.world.phys.AABB;
import java.util.*;
public final class ConveyorGameTests {
 private ConveyorEntity part(GameTestHelper h,Conveyors.Kind kind,int x,int y,int z,Direction d){var r=new BlockPos(x,y,z);h.setBlock(r,Conveyors.BLOCKS.get(kind).defaultBlockState().setValue(ConveyorBlock.FACING,d));var be=h.getBlockEntity(r,ConveyorEntity.class);ConveyorNetwork.register(h.getLevel(),be);return be;}
 private MachineBlockEntity drive(GameTestHelper h,int x,int y,int z,Direction d){var r=new BlockPos(x,y,z);h.setBlock(r,Machines.BLOCKS.get(MachineKind.DRIVE).defaultBlockState().setValue(MachineBlock.FACING,d));var be=h.getBlockEntity(r,MachineBlockEntity.class);be.energy=10*Energy.UNIT;ConveyorNetwork.registerDrive(h.getLevel(),be);return be;}
 private void ticks(GameTestHelper h,int count){var w=h.getLevel();long before=w.getGameTime();try{for(int i=1;i<=count;i++){((ServerLevelData)w.getLevelData()).setGameTime(before+i);ConveyorNetwork.tick(w);}}finally{((ServerLevelData)w.getLevelData()).setGameTime(before);}}
 private Container chest(GameTestHelper h,int x,int z){h.setBlock(new BlockPos(x,1,z),Blocks.CHEST);return (Container)h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(x,1,z)));}
 private int count(Container c,Item item){int n=0;for(int i=0;i<c.getContainerSize();i++)if(c.getItem(i).is(item))n+=c.getItem(i).getCount();return n;}
 @GameTest public void loaderBeltReceiverConserveSixteenItems(GameTestHelper h){
  var source=chest(h,1,2);var destination=chest(h,6,2);source.setItem(0,new ItemStack(Items.IRON_INGOT,16));part(h,Conveyors.Kind.MANIPULATOR,2,1,2,Direction.EAST);part(h,Conveyors.Kind.BELT,3,1,2,Direction.EAST);part(h,Conveyors.Kind.BELT,4,1,2,Direction.EAST);var receiver=part(h,Conveyors.Kind.MANIPULATOR,5,1,2,Direction.WEST);receiver.reverse=true;var motor=drive(h,3,1,1,Direction.SOUTH);
  ticks(h,240);h.assertTrue(count(source,Items.IRON_INGOT)==0&&count(destination,Items.IRON_INGOT)==16,"Transport lost or duplicated items");h.assertTrue(motor.driveLoad==4,"Manipulator not counted in shared drive load");h.succeed();
 }
 @GameTest public void ghostFilterDoesNotConsumeSampleAndSelectsOnlyMatchingItems(GameTestHelper h){
  var source=chest(h,1,2);var dest=chest(h,5,2);source.setItem(0,new ItemStack(Items.COPPER_INGOT,4));source.setItem(1,new ItemStack(Items.IRON_INGOT,8));var loader=part(h,Conveyors.Kind.MANIPULATOR,2,1,2,Direction.EAST);part(h,Conveyors.Kind.BELT,3,1,2,Direction.EAST);var receiver=part(h,Conveyors.Kind.MANIPULATOR,4,1,2,Direction.WEST);receiver.reverse=true;drive(h,3,1,1,Direction.SOUTH);
  var player=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);var menu=new ConveyorMenu(1,player.getInventory(),loader);menu.setCarried(new ItemStack(Items.IRON_INGOT,23));menu.clicked(0,0,net.minecraft.world.inventory.ContainerInput.PICKUP,player);h.assertTrue(menu.getCarried().getCount()==23&&loader.filter.getItem(0).getCount()==1,"Ghost sample consumed real inventory");loader.filtering=true;
  ticks(h,180);h.assertTrue(count(source,Items.COPPER_INGOT)==4&&count(dest,Items.COPPER_INGOT)==0&&count(dest,Items.IRON_INGOT)==8,"Filter ignored selected type");h.succeed();
 }
 @GameTest public void sixteenSectionLimitDoesNotExtendWithClusteredMotors(GameTestHelper h){
  var positions=new ArrayList<BlockPos>();for(int x=1;x<=6;x++)positions.add(new BlockPos(x,1,1));for(int z=2;z<=6;z++)positions.add(new BlockPos(6,1,z));for(int x=5;x>=1;x--)positions.add(new BlockPos(x,1,6));positions.add(new BlockPos(1,1,5));
  for(int i=0;i<positions.size();i++){var p=positions.get(i);var next=i+1<positions.size()?positions.get(i+1):p.north();Direction d=next.getX()>p.getX()?Direction.EAST:next.getX()<p.getX()?Direction.WEST:next.getZ()>p.getZ()?Direction.SOUTH:Direction.NORTH;part(h,Conveyors.Kind.BELT,p.getX(),p.getY(),p.getZ(),d);}
  var motor=drive(h,1,1,0,Direction.SOUTH);ticks(h,1);h.assertTrue(motor.driveLoad==16&&!h.getBlockEntity(positions.getLast(),ConveyorEntity.class).powered,"Motor exceeded sixteen elements or path range");drive(h,1,1,2,Direction.NORTH);ticks(h,1);h.assertTrue(!h.getBlockEntity(positions.getLast(),ConveyorEntity.class).powered,"Clustered motor incorrectly extended path reach");h.succeed();
 }
 @GameTest public void splitterDistributesEvenAndOddCountsByItem(GameTestHelper h){
  var split=part(h,Conveyors.Kind.SPLITTER,4,1,3,Direction.NORTH);part(h,Conveyors.Kind.BELT,4,1,4,Direction.NORTH);var left=part(h,Conveyors.Kind.BELT,3,1,3,Direction.WEST);var right=part(h,Conveyors.Kind.BELT,5,1,3,Direction.EAST);drive(h,3,1,4,Direction.EAST);
  split.offer(new ItemStack(Items.DIAMOND,4),h.getLevel().getGameTime());ticks(h,30);int a=left.cargo.stream().mapToInt(c->c.stack.getCount()).sum(),b=right.cargo.stream().mapToInt(c->c.stack.getCount()).sum();h.assertTrue(a==2&&b==2,"Splitter divides groups rather than item quantities");h.succeed();
 }
 @GameTest public void fullReceiverHoldsItsHandThenFinishesExactlyOnce(GameTestHelper h){
  var source=chest(h,1,2);var dest=chest(h,5,2);source.setItem(0,new ItemStack(Items.IRON_INGOT,4));part(h,Conveyors.Kind.MANIPULATOR,2,1,2,Direction.EAST);part(h,Conveyors.Kind.BELT,3,1,2,Direction.EAST);var receiver=part(h,Conveyors.Kind.MANIPULATOR,4,1,2,Direction.WEST);receiver.reverse=true;drive(h,3,1,1,Direction.SOUTH);
  int guard=0;while(receiver.hand.isEmpty()&&guard++<150)ticks(h,1);h.assertTrue(!receiver.hand.isEmpty(),"Receiver never picked up item");for(int i=0;i<dest.getContainerSize();i++)dest.setItem(i,new ItemStack(Items.STONE,64));ticks(h,50);h.assertTrue(receiver.hand.getCount()==4,"Full inventory destroyed held items");dest.clearContent();ticks(h,40);h.assertTrue(receiver.hand.isEmpty()&&count(dest,Items.IRON_INGOT)==4,"Held items duplicated or failed delivery");h.succeed();
 }
 @GameTest public void redstoneAndPowerLossStopWithoutLosingCargo(GameTestHelper h){var belt=part(h,Conveyors.Kind.BELT,3,1,3,Direction.EAST);var motor=drive(h,3,1,2,Direction.SOUTH);belt.offer(new ItemStack(Items.COAL,4),h.getLevel().getGameTime());motor.driveMode=1;ticks(h,20);h.assertTrue(belt.cargo.getFirst().progress==0&&belt.status==3,"Default redstone gating ignored");motor.driveMode=0;motor.energy=0;ticks(h,20);h.assertTrue(belt.cargo.getFirst().progress==0&&belt.status==2,"Unpowered belt advanced");motor.energy=Energy.UNIT;ticks(h,5);h.assertTrue(belt.cargo.getFirst().progress>0,"Powered belt failed restart");h.succeed();}
 @GameTest public void saveKeepsCargoHandFiltersAndDiverterState(GameTestHelper h){var be=part(h,Conveyors.Kind.MANIPULATOR,2,1,2,Direction.EAST);be.hand=new ItemStack(Items.GOLD_INGOT,3);be.armPhase=8;be.reverse=true;be.filtering=true;be.filter.setItem(8,new ItemStack(Items.DIAMOND));var saved=be.saveWithFullMetadata(h.getLevel().registryAccess());var copy=(ConveyorEntity)net.minecraft.world.level.block.entity.BlockEntity.loadStatic(be.getBlockPos(),be.getBlockState(),saved,h.getLevel().registryAccess());h.assertTrue(copy!=null&&copy.hand.getCount()==3&&copy.armPhase==8&&copy.reverse&&copy.filtering&&copy.filter.getItem(8).is(Items.DIAMOND),"Reload lost transport state");h.succeed();}
 @GameTest public void rampReservesCompanionAndDropsOneBelt(GameTestHelper h){var be=part(h,Conveyors.Kind.BELT,3,1,3,Direction.EAST);var w=h.getLevel();var p=be.getBlockPos();var s=be.getBlockState().setValue(ConveyorBlock.SLOPE,1);w.setBlock(p,s,3);w.setBlock(p.above(),s.setValue(ConveyorBlock.UPPER,true),3);h.assertTrue(!w.getBlockState(p.above()).canBeReplaced(),"Ramp companion is replaceable");w.destroyBlock(p,true);int belts=0;for(var item:w.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(p).inflate(2)))if(item.getItem().is(Conveyors.ITEMS.get(Conveyors.Kind.BELT)))belts+=item.getItem().getCount();h.assertTrue(belts==1&&w.getBlockState(p.above()).isAir(),"Ramp dropped twice or orphaned companion");h.succeed();}
 @GameTest public void pressUsesEightTEForEachMetalPlate(GameTestHelper h){var r=new BlockPos(2,1,2);h.setBlock(r,Machines.BLOCKS.get(MachineKind.PRESS));var press=h.getBlockEntity(r,MachineBlockEntity.class);for(var pair:Machines.PLATES.entrySet()){press.energy=300*Energy.UNIT;press.setItem(0,new ItemStack(pair.getKey()));press.setItem(1,ItemStack.EMPTY);for(int i=0;i<80;i++){press.beginTick();press.finishTick();}h.assertTrue(press.getItem(1).is(pair.getValue())&&press.energy==292*Energy.UNIT,"Press time, output or cost incorrect");}h.succeed();}
 @GameTest public void automationRespectsMachineSidesAndDoesNotExtractBatteries(GameTestHelper h){var r=new BlockPos(2,1,2);h.setBlock(r,Machines.BLOCKS.get(MachineKind.PRESS));var press=h.getBlockEntity(r,MachineBlockEntity.class);press.setItem(2,new ItemStack(Machines.BATTERY));var arm=part(h,Conveyors.Kind.MANIPULATOR,3,1,2,Direction.EAST);h.assertTrue(ItemAccess.peek(h.getLevel(),press.getBlockPos(),Direction.NORTH,arm).isEmpty(),"Automation extracted battery");press.setItem(1,new ItemStack(Machines.PLATES.get(Items.IRON_INGOT),2));h.assertTrue(ItemAccess.peek(h.getLevel(),press.getBlockPos(),Direction.NORTH,arm).getCount()==2,"Output face not exposed");h.assertTrue(ItemAccess.peek(h.getLevel(),press.getBlockPos(),Direction.SOUTH,arm).isEmpty(),"Disabled energy face exposes items");h.succeed();}
 @GameTest public void risingBeltCarriesCargoToUpperLevel(GameTestHelper h){var start=part(h,Conveyors.Kind.BELT,2,1,2,Direction.EAST);var ramp=part(h,Conveyors.Kind.BELT,3,1,2,Direction.EAST);var w=h.getLevel();var p=ramp.getBlockPos();var state=ramp.getBlockState().setValue(ConveyorBlock.SLOPE,1);w.setBlock(p,state,3);w.setBlock(p.above(),state.setValue(ConveyorBlock.UPPER,true),3);var end=part(h,Conveyors.Kind.BELT,4,2,2,Direction.EAST);drive(h,2,1,1,Direction.SOUTH);start.offer(new ItemStack(Items.COPPER_INGOT,4),w.getGameTime());ticks(h,90);h.assertTrue(start.cargo.isEmpty()&&ramp.cargo.isEmpty()&&end.cargo.size()==1&&end.cargo.getFirst().stack.getCount()==4,"Ascending line lost cargo or failed height transition");h.succeed();}
 @GameTest public void downwardCompanionIsRemovedAndRefundedOnce(GameTestHelper h){var be=part(h,Conveyors.Kind.BELT,3,3,3,Direction.NORTH);var w=h.getLevel();var p=be.getBlockPos();var state=be.getBlockState().setValue(ConveyorBlock.SLOPE,2);w.setBlock(p,state,3);w.setBlock(p.below(),state.setValue(ConveyorBlock.UPPER,true),3);h.assertTrue(ConveyorBlock.owner(p.below(),w.getBlockState(p.below())).equals(p),"Descending companion points to wrong owner");w.destroyBlock(p,true);int count=0;for(var item:w.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(p).inflate(2)))if(item.getItem().is(Conveyors.ITEMS.get(Conveyors.Kind.BELT)))count+=item.getItem().getCount();h.assertTrue(count==1&&w.getBlockState(p.below()).isAir(),"Descending ramp duplicated drop or left obstruction");h.succeed();}
 @GameTest public void liveGeneratorFeedsMechanicalLineThroughDriveInput(GameTestHelper h){var belt=part(h,Conveyors.Kind.BELT,3,1,3,Direction.EAST);var motor=drive(h,3,1,2,Direction.SOUTH);motor.energy=0;var r=new BlockPos(3,1,1);h.setBlock(r,Machines.BLOCKS.get(MachineKind.GENERATOR).defaultBlockState().setValue(MachineBlock.FACING,Direction.NORTH));var gen=h.getBlockEntity(r,MachineBlockEntity.class);gen.setItem(0,new ItemStack(Items.COAL));EnergyNetwork.register(h.getLevel(),gen);EnergyNetwork.register(h.getLevel(),motor);var w=h.getLevel();long before=w.getGameTime();try{for(int i=1;i<=60;i++){((ServerLevelData)w.getLevelData()).setGameTime(before+i);EnergyNetwork.tick(w);ConveyorNetwork.tick(w);}}finally{((ServerLevelData)w.getLevelData()).setGameTime(before);}h.assertTrue(belt.powered&&motor.energy>0&&gen.outgoing>0,"Drive not integrated with real energy input");h.succeed();}
 @GameTest(maxTicks=80) public void movingSurfacePushesLivingEntitiesAndSneakingHoldsPosition(GameTestHelper h){var belt=part(h,Conveyors.Kind.BELT,3,1,3,Direction.EAST);var other=part(h,Conveyors.Kind.BELT,3,1,5,Direction.EAST);drive(h,3,1,2,Direction.SOUTH);drive(h,3,1,6,Direction.NORTH);var a=h.spawn(net.minecraft.world.entity.EntityTypes.ARMOR_STAND,new BlockPos(3,1,3));var b=h.spawn(net.minecraft.world.entity.EntityTypes.ARMOR_STAND,new BlockPos(3,1,5));var p=belt.getBlockPos();var q=other.getBlockPos();a.setPos(p.getX()+.35,p.getY()+.25,p.getZ()+.5);b.setPos(q.getX()+.35,q.getY()+.25,q.getZ()+.5);b.setShiftKeyDown(true);double ax=a.getX(),bx=b.getX();h.runAtTickTime(30,()->{h.assertTrue(a.getX()>ax+.03,"Powered surface did not push standing entity");h.assertTrue(Math.abs(b.getX()-bx)<.03,"Sneaking entity was pushed");h.succeed();});}

}
